public static async Task<List<(string Title, int Views)>> GetPostTitlesAndViewsAsync(BlogContext blogContext, CancellationToken cancellationToken)
{
    var postTitlesAndViewsQuery = from post in blogContext.Posts.AsNoTracking()
                                  select (Title: post.Title, Views: post.Views);

    var postTitlesAndViews = await postTitlesAndViewsQuery.ToListAsync(cancellationToken);

    return postTitlesAndViews;
}
